import{_ as a,o as e,c as t,ae as i}from"./chunks/framework.BajMXG5H.js";const g=JSON.parse('{"title":"トラブルシューティング","description":"","frontmatter":{},"headers":[],"relativePath":"ja/reference/troubleshooting.md","filePath":"ja/reference/troubleshooting.md"}'),o={name:"ja/reference/troubleshooting.md"};function l(n,s,r,p,h,d){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h1><h2 id="gatekeeperがアプリをブロックする" tabindex="-1">Gatekeeperがアプリをブロックする <a class="header-anchor" href="#gatekeeperがアプリをブロックする" aria-label="Permalink to &quot;Gatekeeperがアプリをブロックする&quot;">​</a></h2><p>OrchestraはApple Developer証明書で署名されていないため、macOS Gatekeeperがブロックする場合があります。</p><p><strong>解決策:</strong> 以下のいずれかの方法で解決できます:</p><ol><li><strong>システム設定</strong>: <strong>システム設定 → プライバシーとセキュリティ</strong> を開き、下にスクロールしてブロックされたアプリの横にある <strong>「このまま開く」</strong> をクリック</li><li><strong>ターミナル</strong>: 以下のコマンドを実行:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/Orchestra.app</span></span></code></pre></div><h2 id="hookイベントが表示されない" tabindex="-1">Hookイベントが表示されない <a class="header-anchor" href="#hookイベントが表示されない" aria-label="Permalink to &quot;Hookイベントが表示されない&quot;">​</a></h2><p>セッションがOrchestraのダッシュボードに表示されない場合。</p><p><strong>Hook設定を確認:</strong></p><ol><li><code>~/.claude/settings.json</code>を開く</li><li><code>hooks</code>セクションに必要な全イベントが含まれているか確認: PreToolUse, PostToolUse, Stop, Notification, SubagentStart, SubagentStop, SessionStart, SessionEnd, UserPromptSubmit, PermissionRequest, PreCompact, TeammateIdle, TaskCompleted</li><li>curlコマンドが<code>http://localhost:3008/api/ingest/hook</code>を指していることを確認</li></ol><p><strong>Orchestraが実行中か確認:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ポート3008がリッスンしているか確認</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :3008</span></span></code></pre></div><p>何もリッスンしていない場合、Orchestraが起動されていることを確認してください。</p><h2 id="チームモードが動作しない" tabindex="-1">チームモードが動作しない <a class="header-anchor" href="#チームモードが動作しない" aria-label="Permalink to &quot;チームモードが動作しない&quot;">​</a></h2><p>Agent Teamsモードで実行しているセッションに虹色枠が表示されない場合。</p><p><strong>考えられる原因:</strong></p><ol><li><strong>hookイベントが不足</strong> — <code>~/.claude/settings.json</code>に<code>TeammateIdle</code>と<code>TaskCompleted</code>のhookが設定されているか確認してください。チーム検出にはこれらが必須です。</li><li><strong>セッションが同じtmuxウィンドウにない</strong> — チーム検出は同じtmuxウィンドウ内で複数のセッションが共有していることに依存します。チームメンバーが同じウィンドウ内のペインで実行されていることを確認してください。</li><li><strong>Agent Teamsが有効でない</strong> — Claude Code環境に<code>CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS=1</code>が設定されていることを確認してください。</li></ol><h2 id="ポート3008が使用中" tabindex="-1">ポート3008が使用中 <a class="header-anchor" href="#ポート3008が使用中" aria-label="Permalink to &quot;ポート3008が使用中&quot;">​</a></h2><p>別のアプリケーションがポート3008を使用しており、Orchestraが起動できない場合。</p><p><strong>解決策:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ポート3008を使用しているプロセスを確認</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :3008</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 必要に応じてプロセスをkill</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -9</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>その後、Orchestraを再起動してください。</p><h2 id="セッションが更新されない" tabindex="-1">セッションが更新されない <a class="header-anchor" href="#セッションが更新されない" aria-label="Permalink to &quot;セッションが更新されない&quot;">​</a></h2><p>セッションは表示されるがリアルタイムで更新されない場合。</p><p><strong>考えられる原因:</strong></p><ol><li><strong>Claude Codeが再起動された</strong> — Orchestraを再起動して接続をリフレッシュ</li><li><strong>Hook設定が変更された</strong> — <code>~/.claude/settings.json</code>のhooksを確認</li><li><strong>ネットワークの問題</strong> — <code>localhost:3008</code>にアクセス可能か確認</li></ol><h2 id="アプリが起動時にクラッシュする" tabindex="-1">アプリが起動時にクラッシュする <a class="header-anchor" href="#アプリが起動時にクラッシュする" aria-label="Permalink to &quot;アプリが起動時にクラッシュする&quot;">​</a></h2><p><strong>ログを確認:</strong></p><ol><li><code>Console.app</code>を開く</li><li>&quot;Orchestra&quot;でフィルタ</li><li>クラッシュレポートやエラーメッセージを確認</li></ol><p><strong>一般的な解決策:</strong></p><ul><li>アプリを削除し、新しいDMGから再インストール</li><li>macOSが11.0以上に更新されていることを確認</li><li>ポート3008で競合するアプリケーションがないか確認</li></ul><h2 id="jumpボタンが動作しない" tabindex="-1">Jumpボタンが動作しない <a class="header-anchor" href="#jumpボタンが動作しない" aria-label="Permalink to &quot;Jumpボタンが動作しない&quot;">​</a></h2><p>Jumpボタンは表示されるがクリックしてもセッションに切り替わらない場合。</p><p><strong>考えられる原因:</strong></p><ol><li><strong>tmuxがインストールされていない</strong> — <code>brew install tmux</code>でインストール</li><li><strong>セッションがtmux内にない</strong> — Claude Codeセッションはtmuxセッション内で実行する必要があります</li><li><strong>iTerm2が実行されていない</strong> — フルフォーカスサポートにはiTerm2を使用してください</li></ol>`,35)])])}const k=a(o,[["render",l]]);export{g as __pageData,k as default};
